targets.rawSql:
SELECT 'GMV' AS "Chỉ tiêu", sumIf(gmv, order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw})) AS "Kỳ chọn", sumIf(gmv, order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw} * 2) DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY) AS "Kỳ trước",
       if(min(order_date) <= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw}*2) DAY,
          (sumIf(gmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}))-sumIf(gmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw} * 2) DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY))/nullIf(sumIf(gmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw} * 2) DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY),0),NULL) AS "Thay đổi"
FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'NMV',sumIf(nmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw})),sumIf(nmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw} * 2) DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY),
       if(min(order_date) <= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw}*2) DAY,
          (sumIf(nmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}))-sumIf(nmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw} * 2) DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY))/nullIf(sumIf(nmv,order_date >= (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL (${period_days:raw} * 2) DAY AND order_date < (SELECT max(order_date) FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}) - INTERVAL ${period_days:raw} DAY),0),NULL)
FROM mart.daily_sales WHERE refresh_id = ${refresh_id:raw}

SELECT 'Kho vận' AS "Đội phụ trách", 'SKU cần bổ sung' AS "Tín hiệu",
       countIf(needs_reorder) AS "Số lượng", 'Mở Nhà bán & tồn kho; ưu tiên SKU có khoảng thiếu lớn.' AS "Hành động"
FROM mart.inventory_risk WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Seller success','Shop cần rà SLA / hủy',countIf(orders>=30 AND (sla_breaches>0 OR cancel_rate>=0.2)),
       'Xem hàng chờ can thiệp; tách lỗi SLA và hủy chưa thanh toán trước khi xử lý shop.'
FROM mart.shop_performance WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Chăm sóc khách hàng','Yêu cầu trả hàng đang mở',sum(open),
       'Mở Đơn hàng & trải nghiệm; phân bổ người xử lý theo lý do trả hàng.'
FROM mart.returns_summary WHERE refresh_id = ${refresh_id:raw}
UNION ALL SELECT 'Fulfillment','Đơn chờ shop đóng gói',sumIf(orders,status IN ('TO_SHIP','READY_TO_SHIP')),
       'Theo dõi năng lực xử lý; mart chưa có tuổi từng đơn nên chưa kết luận quá hạn.'
FROM mart.order_status_summary WHERE refresh_id = ${refresh_id:raw}
